#!/usr/bin/env python3
"""
aplicar_cambios_cliente.py — Increscendo, área de clientes (ronda 2)

Aplica, sin IA, todos los cambios de la ronda 2 sobre el proyecto
"increscendo-cliente" (el que descomprimiste del zip completo):

  - Login: panel de marca más oscuro con anillos; titular en 3 líneas.
  - Inicio: resumen de saldos (tarjeta, lo que debes, pagado este mes).
  - Movimientos: tabla de escritorio con filtros, paginación y detalle lateral.
  - Préstamos: visibles para todos, pantalla tipo "Mi tarjeta" y proceso en 5 pasos.
  - Barra inferior móvil en azul navy.
  - Ayuda dentro de la app (/ayuda) y Perfil en dos columnas en escritorio.

Uso (desde la carpeta del proyecto, donde está package.json):
    python aplicar_cambios_cliente.py --dry-run   # solo muestra qué cambiaría
    python aplicar_cambios_cliente.py             # aplica los cambios
    python aplicar_cambios_cliente.py --force     # aplica aunque un archivo tenga cambios tuyos

Antes de tocar nada respalda cada archivo en _respaldo_AAAAMMDD_HHMM/ (fuera de src).
Si un archivo ya tiene el contenido nuevo, lo salta: se puede correr dos veces.
"""
import argparse, base64, hashlib, os, shutil, sys
from datetime import datetime

# (estado, ruta, sha256 de la versión anterior, contenido nuevo en base64)
# estado: A = nuevo, M = modificado, D = eliminado
CHANGES = [
    ('M', '.env.example', 'cb17162d6c526ffb7ad0ced16eb9c83f490e25fa75ecf133fa8728961b8c9828', ''),
    ('M', 'docs/CONTRATOS_BACKEND_CLIENTE.md', '6b5d6afd9144d730b9351579bb085274132072543f8df1b7080a21fe60c8f343', ''),
    ('M', 'src/app/router.tsx', '35349b8a9bf2a1c1bd3ed3b65c8c19ac1566312293b8cf6147c5d23822188fa5', ''),
    ('M', 'src/client/components/AuthShell.tsx', '0368f22923435f82c3049fe3e5d61d23d40b731dc229eac90c6d764ffe1f2753', ''),
    ('M', 'src/client/components/ClientLayout.tsx', 'e56cb1dc7ee201c563588d82d61727c83869926ed42703246c02428947121ba9', ''),
    ('A', 'src/client/components/MovementsTable.tsx', None, ''),
    ('M', 'src/client/components/ui.tsx', '01354a55a71e678eecd1c958e7d498e98ed98f2f89999b5cb8a29775a2019389', ''),
    ('M', 'src/client/lib/api.ts', '76620a51e9f8b4e3eeee173d06d026b6bb9fe86d316598e87f494f6b5c923ae7', ''),
    ('M', 'src/client/lib/env.ts', 'af7b5d60316a5c3eb892001aa1a3c912d4283041ee3fff7a18ef1f356fcbe131', ''),
    ('M', 'src/client/lib/format.ts', '097c9212009161774dbab4d9b9a5cbaa9969f3236e74361b80b65fb23713db08', ''),
    ('M', 'src/client/lib/rules.ts', '6f4278aefc914e24de320c0b8fdcdcf9b3db3bf93292fc902f0501fb018e41e8', ''),
    ('A', 'src/client/pages/Help.tsx', None, ''),
    ('M', 'src/client/pages/Home.tsx', '1fac67201339c7acb1156cb97ed302be084c3b617122eb7d6aa85b121084aa60', ''),
    ('M', 'src/client/pages/LoanDetail.tsx', '29490cba75d67a9433d29c101fb95a1ae4ed2727dc8ddbce3beaa1f5876afb44', ''),
    ('M', 'src/client/pages/LoanFlow.tsx', 'a9d1f2e999a73a8d6a69ff23cfc29d330893fb3b63144a93cc02982f3796948e', ''),
    ('M', 'src/client/pages/Loans.tsx', '97b760abb7f04ca691f433c4c49c53541e3104a9b13747f61c7f98e8ea50149a', ''),
    ('M', 'src/client/pages/Movements.tsx', 'ae8036bcba500c76e2e7dd0dddc033abb76f78573c0c20d4b4f320a510ecd9ef', ''),
    ('M', 'src/client/pages/Profile.tsx', 'a387680973f30538c736c57044023c286dace30ff88098f8e4e2add8556036aa', ''),
]

def sha(data: bytes) -> str:
    # Ignora diferencias de fin de línea (Windows CRLF vs LF).
    return hashlib.sha256(data.replace(b"\r\n", b"\n")).hexdigest()

def main() -> int:
    ap = argparse.ArgumentParser(description="Aplica la ronda 2 del área de clientes de Increscendo.")
    ap.add_argument("--dry-run", action="store_true", help="No escribe nada; solo muestra qué haría.")
    ap.add_argument("--force", action="store_true", help="Sobrescribe aunque el archivo tenga cambios locales.")
    ap.add_argument("--root", default=".", help="Carpeta del proyecto (por defecto, la actual).")
    args = ap.parse_args()

    root = os.path.abspath(args.root)
    if not os.path.isfile(os.path.join(root, "package.json")) or not os.path.isdir(os.path.join(root, "src", "client")):
        print("ERROR: no encuentro package.json y src/client en", root)
        print("Corre el script desde la carpeta del proyecto increscendo-cliente.")
        return 1

    plan, conflicts = [], []
    for status, rel, old_hash, b64 in CHANGES:
        path = os.path.join(root, *rel.split("/"))
        new = base64.b64decode(b64) if b64 is not None else None
        exists = os.path.isfile(path)
        current = open(path, "rb").read() if exists else None
        if status == "D":
            if not exists:
                continue
            action = "eliminar"
        else:
            if exists and new is not None and sha(current) == sha(new):
                continue  # ya aplicado
            action = "crear" if not exists else "actualizar"
        if exists and old_hash and sha(current) != old_hash and (new is None or sha(current) != sha(new)):
            conflicts.append(rel)
        plan.append((action, rel, path, new, exists))

    if not plan:
        print("Nada que hacer: los cambios ya están aplicados.")
        return 0

    print(f"Proyecto: {root}")
    for action, rel, *_ in plan:
        flag = "  (tiene cambios tuyos)" if rel in conflicts else ""
        print(f"  {action:<10} {rel}{flag}")

    if conflicts and not args.force:
        print()
        print("Estos archivos no coinciden con la versión que te entregué (los editaste o son de otra versión):")
        for c in conflicts:
            print("   -", c)
        print("No apliqué nada. Revisa y, si quieres sobrescribirlos (quedan respaldados), usa --force.")
        return 2

    if args.dry_run:
        print("\n--dry-run: no se escribió nada.")
        return 0

    backup = os.path.join(root, "_respaldo_" + datetime.now().strftime("%Y%m%d_%H%M"))
    for action, rel, path, new, exists in plan:
        if exists:
            dst = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(path, dst)
        if action == "eliminar":
            os.remove(path)
        else:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "wb") as f:
                f.write(new)

    gi = os.path.join(root, ".gitignore")
    try:
        txt = open(gi, encoding="utf-8").read() if os.path.isfile(gi) else ""
        if "_respaldo_" not in txt:
            with open(gi, "a", encoding="utf-8") as f:
                f.write("\n# Respaldos de scripts de cambios\n_respaldo_*/\n")
    except OSError:
        pass

    print(f"\nListo: {len(plan)} archivo(s). Respaldo en {os.path.relpath(backup, root)}")
    print("Ahora: detén el servidor (Ctrl+C) y vuelve a correr  npm run dev")
    return 0

if __name__ == "__main__":
    sys.exit(main())
